    // ── STATE ──
    private string? _maTruongBo;
    private string? _selectedNamHoc;
    private string? _selectedCapHoc;

    private List<KhoiHoc_DTO>       _khoiList      = new();
    private List<LopHoc_DTO>        _allLopList    = new();



    // Filter cho toolbar

    private int _filterMaKhoi;
    private int _filterMaLop;
    private List<LopHoc_DTO> _lopFilterList = new();

    // Danh sách thành viên
    private List<ScnBanDaiDienCMHSDTO> _allList      = new();
    private List<ScnBanDaiDienCMHSDTO> _filteredList = new();
    private List<ScnBanDaiDienCMHSDTO> _displayList  = new();

    private string _searchTerm = "";
    private bool   _isLoading  = false;

    // Phân trang
    private int _currentPage = 1;
    private int _pageSize    = 15;

    // Form
    private bool              _showForm  = false;
    private bool              _isSaving  = false;
    private ScnBanDaiDienCMHSDTO _editModel = new();
    private List<LopHoc_DTO>  _lopFormList = new();
    private string            _hoTenError = "";

    // Xóa
    private bool              _showDeleteConfirm = false;
    private ScnBanDaiDienCMHSDTO? _deleteTarget     = null;

    // Toast
    private string _toastMsg  = "";
    private string _toastCss  = "";
    private string _toastIcon = "";
    private System.Threading.CancellationTokenSource? _toastCts;

    // Trách nhiệm options
    private static readonly List<string> _trachNhiemOptions = new()
    {
        "Trưởng ban",
        "Phó ban",
        "Thư ký",
        "Thủ quỹ",
        "Thành viên",
    };

    // ── LIFECYCLE ──
    protected override async Task OnInitializedAsync()
    {
        _maTruongBo     = await BrowserStorageService.GetMaTruongBoAsync(JS);
        _selectedNamHoc = await BrowserStorageService.GetItem(JS, "selectedNamHoc");
        _selectedCapHoc = await BrowserStorageService.GetItem(JS, "selectedLevel");

        await LoadAll();
    }

    private async Task LoadAll()
    {
        _isLoading = true;
        StateHasChanged();
        try
        {
            var taskKhoi = TruongService.hGetDanhSachKhoi(_maTruongBo ?? "", _selectedCapHoc ?? "1");
            var taskLop  = TruongService.hGetDanhSachLop(_maTruongBo ?? "", _selectedCapHoc ?? "1", _selectedNamHoc ?? "");
            var taskData = TruongService.hGetBanDaiDienCMHS();

            await Task.WhenAll(taskKhoi, taskLop, taskData);

            _khoiList   = taskKhoi.Result;
            _allLopList = taskLop.Result;
            _allList    = taskData.Result;

            _lopFilterList = _allLopList.ToList();
            ApplyFilter();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"LoadAll error: {ex.Message}");
            await ShowToast("Lỗi tải dữ liệu!", "toast-error", "error");
        }
        finally
        {
            _isLoading = false;
            StateHasChanged();
        }
    }

    // ── FILTER TOOLBAR ──
    private void OnFilterKhoiChanged(ChangeEventArgs e)
    {
        _filterMaKhoi = int.TryParse(e.Value?.ToString(), out var kv) ? kv : 0;
        _filterMaLop  = 0;
        _lopFilterList = _filterMaKhoi == 0
            ? _allLopList.ToList()
            : _allLopList.Where(l => l.MaKhoi == _filterMaKhoi).ToList();
        ApplyFilter();
    }

    private void OnFilterLopChanged(ChangeEventArgs e)
    {
        _filterMaLop = int.TryParse(e.Value?.ToString(), out var lv) ? lv : 0;
        ApplyFilter();
    }

    private void ApplyFilter()
    {
        var q = _allList.AsEnumerable();

        // Filter khối
        if (_filterMaKhoi > 0)
        {
            q = q.Where(m => m.MaKhoi == _filterMaKhoi);
        }

        // Filter lớp
        if (_filterMaLop > 0)
        {
            q = q.Where(m => m.MaLop == _filterMaLop);
        }

        // Search
        if (!string.IsNullOrWhiteSpace(_searchTerm))
        {
            var t = _searchTerm.Trim();
            q = q.Where(m =>
                (m.HoTen?.Contains(t, StringComparison.OrdinalIgnoreCase) == true) ||
                (m.SoDienThoai?.Contains(t) == true) ||
                (m.NgheNghiep?.Contains(t, StringComparison.OrdinalIgnoreCase) == true));
        }

        _filteredList = q.ToList();
        _currentPage  = 1;
        BuildPagedList();
        StateHasChanged();
    }

    private void BuildPagedList()
    {
        _displayList = _filteredList
            .Skip((_currentPage - 1) * _pageSize)
            .Take(_pageSize)
            .ToList();
    }

    private void OnPageChanged(int page)      { _currentPage = page; BuildPagedList(); StateHasChanged(); }
    private void OnPageSizeChanged(int size)  { _pageSize = size; _currentPage = 1; BuildPagedList(); StateHasChanged(); }

    // ── FORM ──
    private void OpenAddForm()
    {
        _editModel  = new ScnBanDaiDienCMHSDTO();
        _hoTenError = "";
        _lopFormList = _allLopList.ToList();
        _showForm   = true;
    }

    private void OpenEditForm(ScnBanDaiDienCMHSDTO m)
    {
        _editModel  = new ScnBanDaiDienCMHSDTO
        {
            Id          = m.Id,
            HoTen       = m.HoTen,
            NgheNghiep  = m.NgheNghiep,
            ChoOHienNay = m.ChoOHienNay,
            SoDienThoai = m.SoDienThoai,
            TrachNhiem  = m.TrachNhiem,
            MaKhoi      = m.MaKhoi,
            MaLop       = m.MaLop,
        };
        _hoTenError = "";

        // Lớp theo khối đã chọn
        _lopFormList = m.MaKhoi.HasValue && m.MaKhoi > 0
            ? _allLopList.Where(l => l.MaKhoi == m.MaKhoi).ToList()
            : _allLopList.ToList();

        _showForm = true;
    }

    private void CloseForm() { _showForm = false; _hoTenError = ""; }

    private void OnFormKhoiChanged(ChangeEventArgs e)
    {
        var khoiInt = int.TryParse(e.Value?.ToString(), out var kv) ? kv : 0;
        _editModel.MaKhoi = khoiInt == 0 ? null : khoiInt;
        _editModel.MaLop  = null;
        _lopFormList = khoiInt == 0
            ? _allLopList.ToList()
            : _allLopList.Where(l => l.MaKhoi == khoiInt).ToList();
    }

    private async Task SaveMember()
    {
        if (string.IsNullOrWhiteSpace(_editModel.HoTen))
        {
            _hoTenError = "Vui lòng nhập họ và tên!";
            return;
        }

        _isSaving = true;
        StateHasChanged();
        try
        {
            await TruongService.hUpsertBanDaiDienCMHS(_editModel);
            CloseForm();
            await LoadAll();
            await ShowToast(
                _editModel.Id > 0 ? "Cập nhật thành công!" : "Thêm mới thành công!",
                "toast-success", "check_circle");
        }
        catch (Exception ex)
        {
            Console.WriteLine(ex);
            await ShowToast("Da xay ra loi, vui long thu lai!", "toast-err", "error");
        }
        finally { _isSaving = false; StateHasChanged(); }
    }

    // ── DELETE ──
    private void AskDelete(ScnBanDaiDienCMHSDTO m) { _deleteTarget = m; _showDeleteConfirm = true; }

    private async Task ConfirmDelete()
    {
        if (_deleteTarget == null) return;
        _isSaving = true;
        StateHasChanged();
        try
        {
            await TruongService.hDeleteBanDaiDienCMHS(_deleteTarget.Id);
            _showDeleteConfirm = false;
            _deleteTarget      = null;
            await LoadAll();
            await ShowToast("Đã xóa thành viên!", "toast-success", "check_circle");
        }
        catch (Exception ex)
        {
            Console.WriteLine(ex);
            await ShowToast("Da xay ra loi, vui long thu lai!", "toast-err", "error");
        }
        finally { _isSaving = false; StateHasChanged(); }
    }

    // ── HELPERS ──
    private string GetTenLop(int maLop)
    {
        var lop = _allLopList.FirstOrDefault(l => l.IdLopBo == maLop);
        return lop?.TenLop ?? "";
    }

    private string GetTenKhoi(int maKhoi)
    {
        var k = _khoiList.FirstOrDefault(k => k.MaKhoi == maKhoi);
        return k?.TenKhoi ?? maKhoi.ToString();
    }

    private static int ParseKhoiStr(string? s) =>
        int.TryParse(s, out var v) ? v : 0;

    private int ParseKhoi(string? s) => ParseKhoiStr(s);

    private static int? ParseLop(string? s) =>
        int.TryParse(s, out var v) ? v : null;

    private static string GetTrachNhiemCss(string? tn) => tn switch
    {
        "Trưởng ban" => "badge-truong",
        "Phó ban"    => "badge-pho",
        "Thư ký"     => "badge-thuky",
        "Thủ quỹ"    => "badge-thuquy",
        _            => "badge-tv",
    };

    private async Task ShowToast(string msg, string css, string icon)
    {
        _toastCts?.Cancel();
        _toastCts  = new System.Threading.CancellationTokenSource();
        _toastMsg  = msg;
        _toastCss  = css;
        _toastIcon = icon;
        StateHasChanged();
        try
        {
            await Task.Delay(3500, _toastCts.Token);
            _toastMsg = "";
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

